"""Feature engineering shared by training and inference."""

from __future__ import annotations

import numpy as np
import pandas as pd

BUSINESS_TYPES = ("cafe", "hotel", "retail")
TARGET_COLUMN = "synthetic_monthly_visits"
TARGET_DEFINITION = (
    "Synthetic monthly customer-visit count generated by a labelled demo formula. "
    "This is not observed sales, footfall, or validated real-world demand."
)
MODEL_MODE = "synthetic_demo"
MODEL_NAME = "RandomForestRegressor"

RAW_FEATURE_COLUMNS = [
    "business_type",
    "latitude",
    "longitude",
    "budget_inr",
    "floor_area_sqft",
    "competitor_count",
    "near_college",
]

NUMERIC_FEATURE_COLUMNS = [
    "latitude",
    "longitude",
    "budget_inr",
    "floor_area_sqft",
    "competitor_count",
    "near_college",
    "log_budget_inr",
    "budget_per_sqft",
]

CATEGORICAL_FEATURE_COLUMNS = ["business_type"]
MODEL_FEATURE_COLUMNS = CATEGORICAL_FEATURE_COLUMNS + NUMERIC_FEATURE_COLUMNS


class InvalidFeatureError(ValueError):
    """Raised when required features are missing, invalid, or mis-typed."""


def engineer_features(frame: pd.DataFrame) -> pd.DataFrame:
    """Add derived columns used by both training and inference."""
    engineered = frame.copy()
    engineered["log_budget_inr"] = np.log1p(engineered["budget_inr"].astype(float))
    area = engineered["floor_area_sqft"].astype(float).clip(lower=1.0)
    engineered["budget_per_sqft"] = engineered["budget_inr"].astype(float) / area
    return engineered


def prepare_model_frame(raw: pd.DataFrame) -> pd.DataFrame:
    """Validate raw inputs and return the exact column order expected by the model."""
    if not isinstance(raw, pd.DataFrame):
        raise InvalidFeatureError("Features must be provided as a pandas DataFrame.")

    missing = [column for column in RAW_FEATURE_COLUMNS if column not in raw.columns]
    if missing:
        raise InvalidFeatureError(f"Missing required features: {', '.join(missing)}.")

    prepared = engineer_features(raw.loc[:, RAW_FEATURE_COLUMNS].copy())
    prepared["business_type"] = prepared["business_type"].astype(str).str.strip().str.lower()
    unknown = sorted(set(prepared["business_type"]) - set(BUSINESS_TYPES))
    if unknown:
        raise InvalidFeatureError(
            f"Unsupported business_type values: {', '.join(unknown)}. "
            f"Allowed: {', '.join(BUSINESS_TYPES)}."
        )

    numeric = prepared[NUMERIC_FEATURE_COLUMNS]
    if numeric.isna().any().any():
        raise InvalidFeatureError("Numeric features contain missing values.")
    if not np.isfinite(numeric.to_numpy(dtype=float)).all():
        raise InvalidFeatureError("Numeric features contain non-finite values.")

    return prepared.loc[:, MODEL_FEATURE_COLUMNS]
